import{c as e,Q as a,j as o,m as l}from"./chunks/framework.8JjYC3xy.js";const g=JSON.parse('{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念和使用场景","frontmatter":{"title":"第一章：Claude Code 是什么","description":"了解 Claude Code 的基本概念和使用场景"},"headers":[],"relativePath":"guide/1-getting-started/1-what-is-claude-code.md","filePath":"guide/1-getting-started/1-what-is-claude-code.md"}'),d={name:"guide/1-getting-started/1-what-is-claude-code.md"};function r(i,t,s,n,u,c){return a(),o("div",null,[...t[0]||(t[0]=[l('<h1 id="第一章-claude-code-是什么" tabindex="-1">第一章：Claude Code 是什么 <a class="header-anchor" href="#第一章-claude-code-是什么" aria-label="Permalink to &quot;第一章：Claude Code 是什么&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会理解 Claude Code 能做什么，不能做什么。</p></div><h2 id="claude-code-是命令行工具-不是网页聊天" tabindex="-1">Claude Code 是命令行工具，不是网页聊天 <a class="header-anchor" href="#claude-code-是命令行工具-不是网页聊天" aria-label="Permalink to &quot;Claude Code 是命令行工具，不是网页聊天&quot;">​</a></h2><p>Claude Code 是一个运行在<strong>终端/命令行</strong>里的工具。你通过打字和它对话，它帮你读写代码。</p><p>这和网页版的 Claude（claude.ai）不一样：</p><ul><li><strong>Claude.ai</strong>：在浏览器里聊天，适合问答、写作、分析</li><li><strong>Claude Code</strong>：在你的电脑里工作，直接读写你的代码文件</li></ul><h2 id="claude-code-能做什么" tabindex="-1">Claude Code 能做什么？ <a class="header-anchor" href="#claude-code-能做什么" aria-label="Permalink to &quot;Claude Code 能做什么？&quot;">​</a></h2><p>Claude Code 是一个 AI 编程助手，但它能做的事远不止编程。</p><h3 id="编程相关" tabindex="-1">编程相关 <a class="header-anchor" href="#编程相关" aria-label="Permalink to &quot;编程相关&quot;">​</a></h3><ul><li><strong>读代码</strong>：帮你理解一个陌生项目的结构</li><li><strong>写代码</strong>：帮你创建新文件或修改现有代码</li><li><strong>解释代码</strong>：用自然语言解释代码在做什么</li><li><strong>调试问题</strong>：帮你找出 bug 并修复</li><li><strong>审查代码</strong>：给你代码优化建议</li><li><strong>辅助 Git</strong>：帮你写 commit message、处理合并冲突</li></ul><h3 id="文档编辑" tabindex="-1">文档编辑 <a class="header-anchor" href="#文档编辑" aria-label="Permalink to &quot;文档编辑&quot;">​</a></h3><p>Claude Code 擅长处理各种文档工作：</p><ul><li><strong>Word 文档</strong>：帮你写报告、写文档、润色文字、总结内容</li><li><strong>Excel 表格</strong>：帮你分析数据、写公式、生成图表、分析趋势</li><li><strong>PPT 制作</strong>：帮你规划演示结构、写内容、调整格式</li><li><strong>Markdown 写作</strong>：写博客、写文档、写邮件（Claude Code 直接支持 .md 格式）</li></ul><h3 id="日常重复性工作" tabindex="-1">日常重复性工作 <a class="header-anchor" href="#日常重复性工作" aria-label="Permalink to &quot;日常重复性工作&quot;">​</a></h3><p>Claude Code 还可以帮你自动化许多日常琐事：</p><ul><li><strong>批量重命名文件</strong>：按规则批量修改文件名</li><li><strong>整理文件夹</strong>：自动归类、移动、清理重复文件</li><li><strong>生成批量文本</strong>：批量生成报告、邮件、模板内容</li><li><strong>数据格式转换</strong>：把 CSV 转成 JSON、把 Excel 转成数据库格式</li><li><strong>日志分析</strong>：帮你从大量日志中提取关键信息</li><li><strong>定时任务</strong>：结合 Cron 定时运行Claude Code的工作</li></ul><div class="tip custom-block"><p class="custom-block-title">小技巧</p><p>由于 Claude Code 能直接读写你的电脑文件，它特别适合需要<strong>批量处理</strong>或<strong>自动化</strong>的任务。相比网页版 Claude，它更适合处理需要多步骤协作的工作。</p></div><h2 id="claude-code-不能做什么" tabindex="-1">Claude Code 不能做什么？ <a class="header-anchor" href="#claude-code-不能做什么" aria-label="Permalink to &quot;Claude Code 不能做什么？&quot;">​</a></h2><p>它不能替你做所有事：</p><ul><li><strong>不能替你做决定</strong>：最终决策权在你手里，Claude 只能提供建议</li><li><strong>不会读心术</strong>：你需要清楚地描述你要什么</li><li><strong>批量操作需要你的确认</strong>：虽然能处理大量文件，但每个操作都需要你确认</li><li><strong>复杂 Excel/PPT 有一定限制</strong>：能做基本编辑，但非常复杂的格式和宏可能需要你进一步调整</li></ul><h2 id="和-chatgpt-copilot-的区别" tabindex="-1">和 ChatGPT / Copilot 的区别 <a class="header-anchor" href="#和-chatgpt-copilot-的区别" aria-label="Permalink to &quot;和 ChatGPT / Copilot 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>特点</th><th>适合场景</th></tr></thead><tbody><tr><td>ChatGPT</td><td>网页聊天，什么都能问</td><td>通用问答、写文章、分析数据</td></tr><tr><td>Copilot</td><td>IDE 插件，边写边补全</td><td>写代码时自动补全</td></tr><tr><td>Claude Code</td><td>命令行工具，深入项目 + 批量自动化</td><td>理解整个项目、文件整理、文档批量生成</td></tr></tbody></table><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>本章不需要任何前置知识。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: Claude Code 要钱吗？</strong></p><p>A: Claude Code 本身免费，但使用 Claude 的 API 需要付费。新用户有免费额度，初期够用。</p><p><strong>Q: 不会命令行能学吗？</strong></p><p>A: 当然可以！教程会从零教你基本的终端命令。</p><p><strong>Q: Claude Code 能帮我做 Word、Excel、PPT 吗？</strong></p><p>A: 可以！Claude Code 能读写这些文件，帮你写内容、分析数据、规划结构。但要注意：复杂的格式和宏可能需要你进一步调整。更多细节请参考「文档编辑」章节。</p><p><strong>Q: Claude Code 能做日常自动化吗？</strong></p><p>A: 可以！比如批量重命名文件、整理文件夹、转换数据格式、分析日志等。Claude Code 能直接操作你的文件系统，非常适合需要多步骤协作的自动化任务。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>下一章我们会学习如何安装 Claude Code。</p><p><a href="/claude-code-guide/guide/1-getting-started/2-installation.html">👉 第二章：安装 Claude Code</a></p>',36)])])}const h=e(d,[["render",r]]);export{g as __pageData,h as default};
